import sys
input = sys.stdin.read

def can_make_elements_equal(arr):
    unique_values = sorted(set(arr))
    if len(unique_values) > 3:
        return "NO"
    if len(unique_values) == 3:
        if unique_values[2] - unique_values[1] == unique_values[1] - unique_values[0]:
            return "YES"
        else:
            return "NO"
    return "YES"

data = input().split()
n = int(data[0])
arr = list(map(int, data[1:n+1]))

print(can_make_elements_equal(arr))
